#!/usr/bin/env python3
"""Generate the complete Three.js frontend JavaScript application."""
import os
import base64

ENCODED_JS = ''

def main():
    os.makedirs("/Users/vasilenko.a/Downloads/MVP/app/static/js", exist_ok=True)
    decoded = base64.b64decode(ENCODED_JS).decode("utf-8")
    with open("/Users/vasilenko.a/Downloads/MVP/app/static/js/app.js", "w") as f:
        f.write(decoded)
    print(f"Generated {len(decoded.splitlines())} lines")

if __name__ == "__main__":
    main()
